html:
{% set sn = get_serial_no(doc.name) %}

<meta name="pdfkit-orientation" content="Portrait"/>
<div class="barcode-label-container">
    <div id="margin-top">0mm</div>
    <div id="margin-left">0mm</div>
    <div id="margin-bottom">0mm</div>
    <div id="margin-right">0mm</div>

    <div id="barcode-label" class="align-middle">
        <div>
            <img src="{{frappe.db.get_value('Company', sn.company, 'company_logo')}}" class="logo"/>
        </div>
        <div class="qr-code-section">
            {{get_qr_code(sn.serial_no)}}
        </div>
        <div class="text-info">
            <div class="title">{{ sn.item_code or doc.item_code }}</div>
            <div class="serial">{{ sn.serial_no }}</div>
            <div class="date">{{ frappe.utils.format_datetime(sn.posting_datetime) }}</div>
            <div class="company">{{ sn.company }}</div>
        </div>

    </div>
</div>

<style>
#margin-top,#margin-left,#margin-bottom,#margin-right {
    display: none;
}

@media screen, print {
    .barcode-label-container {
        padding: 1mm;
        margin: 0;
        min-width: 1.5in;
        max-width: 1.5in;
        min-height: 0.5in;
        max-height: 0.5in;
        font-family: Helvetica, sans-serif;
        display: flex;
        align-items: center;
        box-sizing: border-box;
        color: black;
    }

    #barcode-label {
        display: flex;
        align-items: center;
        width: 100%;
        height: 100%;
    }

    .qr-code-section {
        flex-shrink: 0;
        margin-right: 2mm;
    }

    .qr-code {
        height: 12mm;
        width: 12mm;
        display: block;
        image-rendering: pixelated;
    }

    .text-info {
        flex: 1;
        display: flex;
        flex-direction: column;
        justify-content: center;
        font-weight: bold;
        line-height: 1.1;
        color: black;
    }

    .title {
        font-size: 15px;
        margin-bottom: 1px;
    }

    .serial, .date, .company {
        font-size: 11px;
        margin-bottom: 1px;
    }

    .serial:last-child, .date:last-child, .company:last-child {
        margin-bottom: 0;
    }
    .logo {
        height: 12mm;
        display: inline-block;
        vertical-align: middle;
        image-rendering: pixelated;
    }
}
</style>
